  // Legacy products have one shared pool, not one unit count per size.
  const variantStock = (p, color, size) => hasVariants(p)
    ? cleanStock(p.variants.find(v => v.color === color && v.size === size)?.stock)
    : productColors(p).includes(color) && productSizes(p).includes(size) ? cleanStock(p.stock) : 0;
  const totalStock = p => hasVariants(p) ? p.variants.reduce((n,v) => n + cleanStock(v.stock),0) : cleanStock(p.stock);
  const stockLabel = p => totalStock(p) > 0 ? `${totalStock(p)} in stock` : 'OUT OF STOCK';
  // Keep the older admin stock column aligned with the variant sum.
  products=products.map(p=>hasVariants(p)?{...p,stock:totalStock(p)}:p);
