  function addResponsiveSlideFields(){let saved=getCarouselSlides();document.querySelectorAll('#home-slide-list .home-slide-editor').forEach((row,index)=>{if(row.dataset.responsiveImagesReady)return;let anchor=row.querySelector('.home-slide-image');if(!anchor)return;let slide=saved[index]||{};anchor.insertAdjacentHTML('afterend',`<label class="home-slide-image responsive-slide-image">Tablet image (optional)<input name="tabletImage" value="${esc(slide.tabletImage||'')}" placeholder="1200 × 600 image path or URL"><input type="file" accept="image/*" data-slide-responsive-upload="tabletImage"><small>Tablet: 1200 × 600 px (2:1). Falls back to the desktop image when empty.</small></label><label class="home-slide-image responsive-slide-image">Mobile image (optional)<input name="mobileImage" value="${esc(slide.mobileImage||'')}" placeholder="900 × 900 image path or URL"><input type="file" accept="image/*" data-slide-responsive-upload="mobileImage"><small>Mobile: 900 × 900 px (1:1). Falls back to tablet, then desktop, when empty.</small></label>`);row.dataset.responsiveImagesReady='1';});}
  const responsiveSlideEditorObserver=new MutationObserver(addResponsiveSlideFields);responsiveSlideEditorObserver.observe(app,{childList:true,subtree:true});
  document.addEventListener('change',async e=>{if(!e.target.matches('[data-slide-responsive-upload]')||!e.target.files?.[0])return;let row=e.target.closest('.home-slide-editor'),field=row?.querySelector(`[name="${e.target.dataset.slideResponsiveUpload}"]`);if(!field)return;try{let [image]=await window.SAZ_API.uploadImages([e.target.files[0]],'content');field.value=image;toast('Responsive slide image uploaded.');}catch{toast('Could not read this image. Try a JPG, PNG, or WebP file.');}});
  document.addEventListener('click',e=>{let form=document.getElementById('home-slideshow-form');if(!form)return;let list=document.getElementById('home-slide-list'),add=e.target.closest('[data-slide-add]');if(add){let i=list.querySelectorAll('.home-slide-editor').length;list.insertAdjacentHTML('beforeend',`<article class="home-slide-editor"><header><b>Slide ${i+1}</b><div><button type="button" class="carousel-remove-slide" data-slide-up>&#8593;</button> <button type="button" class="carousel-remove-slide" data-slide-down>&#8595;</button> <button type="button" class="carousel-remove-slide" data-slide-remove>Remove</button></div></header><div class="home-slide-fields"><label class="home-slide-image">Slide image<input name="image" required placeholder="Image path or URL"><input type="file" accept="image/*" data-slide-upload><small>Recommended 1600 &times; 700 px (wide landscape). Uploads are securely stored by the server.</small></label><div class="home-slide-preview"><span>Upload or add an image path</span></div><label>Link to product<select data-slide-product><option value="">Use custom page link</option>${products.filter(p=>p.active!==false).map(p=>`<option value="product.html?id=${encodeURIComponent(p.id)}">${esc(p.name)}</option>`).join('')}</select><input name="link" value="shop.html" required placeholder="product.html?id=product-id"></label></div></article>`);return;}let remove=e.target.closest('[data-slide-remove]');if(remove){remove.closest('.home-slide-editor').remove();[...list.querySelectorAll('.home-slide-editor header b')].forEach((b,i)=>b.textContent=`Slide ${i+1}`);return;}let move=e.target.closest('[data-slide-up],[data-slide-down]');if(move){let row=move.closest('.home-slide-editor');if(move.hasAttribute('data-slide-up')&&row.previousElementSibling)list.insertBefore(row,row.previousElementSibling);if(move.hasAttribute('data-slide-down')&&row.nextElementSibling)list.insertBefore(row.nextElementSibling,row);[...list.querySelectorAll('.home-slide-editor header b')].forEach((b,i)=>b.textContent=`Slide ${i+1}`);}});
