  function addColourImageManager(){let form=document.getElementById('product-form');if(!form||form.dataset.colourImagesReady)return;form.dataset.colourImagesReady='1';let original=products.find(p=>p.id===form.elements.oldId?.value)||{},panel=document.createElement('section');panel.className='admin-field-full colour-image-manager';panel.innerHTML='<div class="colour-image-manager-head"><div><b>Colour-specific gallery images</b><small>When a shopper chooses Black, only Black photos will show. Add multiple photos for every colour.</small></div></div><div class="colour-image-list"></div>';form.querySelector('[name="colors"]')?.closest('label')?.insertAdjacentElement('afterend',panel);let draw=()=>{let old=readVariantImages(form),colors=inventoryOptions(form.elements.colors.value);panel.querySelector('.colour-image-list').innerHTML=colors.length?colors.map(colour=>{let urls=old[colour]||original.variantImages?.[colour]||[];return `<article class="colour-image-row"><header><b>${esc(colour)}</b><small>Shown when ${esc(colour)} is selected</small></header><label>Image URLs / local paths<textarea data-colour-image-urls data-colour="${esc(colour)}" rows="3" placeholder="One ${esc(colour)} image per line">${esc(urls.join('\n'))}</textarea></label><label class="colour-image-upload">Upload ${esc(colour)} images<input type="file" accept="image/*" multiple data-colour-image-upload data-colour="${esc(colour)}"><small>Uploads are kept separate from the main product gallery.</small></label></article>`;}).join(''):'<p class="muted">Enter at least one colour above to assign its images.</p>';};draw();form.elements.colors?.addEventListener('input',draw);panel.addEventListener('change',e=>{if(!e.target.matches('[data-colour-image-upload]')||!e.target.files?.length)return;let field=panel.querySelector(`[data-colour-image-urls][data-colour="${CSS.escape(e.target.dataset.colour)}"]`);window.SAZ_API.uploadImages(e.target.files,'products').then(images=>{field.value=[field.value.trim(),...images].filter(Boolean).join('\n');toast(`${images.length} ${e.target.dataset.colour} image(s) added.`);}).catch(()=>toast('Could not read one of those images.'));});}
