  function add(id,qty=1,size=null,color=null){let p=product(id);size=size||(productSizes(p).includes('M')?'M':productSizes(p)[0]);color=color||(productColors(p)[0]);let available=variantStock(p,color,size);if(available<=0){toast('This colour and size is currently out of stock');return false;}let row=cart.find(x=>x.id===id&&x.size===size&&(x.color||p.color)===color),next=(row?.qty||0)+qty;if(next>available){toast(`Only ${available} available in ${color} / ${size}`);return false;}if(row)row.qty=next;else cart.push({id,qty,size,color});persistCart();toast(`${p.name} added to your cart`);return true;}
  function toast(msg){let old=document.querySelector('.toast');if(old)old.remove();let el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),3100);}
  function showSearch(){document.querySelector('.site-search-overlay')?.remove();let overlay=document.createElement('div');overlay.className='site-search-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Search the store');overlay.innerHTML=`<section class="site-search-box"><header><div><span class="eyebrow">SAZ HOUSE</span><h2>Search the store</h2></div><button type="button" class="site-search-close" aria-label="Close search">×</button></header><form><div class="site-search-input-wrap"><span>⌕</span><input type="search" autocomplete="off" placeholder="Search products, categories..." aria-label="Search products"></div><div class="site-search-suggestions"></div><footer><small>Type to see products · Press Enter to view all results</small><kbd>ESC</kbd></footer></form></section>`;document.body.append(overlay);let input=overlay.querySelector('input'),suggestions=overlay.querySelector('.site-search-suggestions'),close=()=>overlay.remove();function fill(){let q=input.value.trim().toLowerCase(),matches=products.filter(p=>p.active!==false&&(p.name.toLowerCase().includes(q)||p.category.toLowerCase().includes(q))).slice(0,5);suggestions.innerHTML=q?matches.map(p=>`<a href="product.html?id=${encodeURIComponent(p.id)}">${p.image?`<img src="${esc(p.image)}" alt="">`:'<span class="search-product-dot">SZ</span>'}<span><b>${esc(p.name)}</b><small>${esc(p.category)} · ${money(p.price)}</small></span><i>→</i></a>`).join('')+`<a class="search-all" href="search.html?q=${encodeURIComponent(input.value.trim())}">See all results for “${esc(input.value.trim())}” →</a>`:'<p class="search-hint">Popular: Hoodie, T-shirt, Cap</p>';if(q&&!matches.length)suggestions.innerHTML=`<p class="search-hint">No matching products yet. Press Enter to see search results.</p><a class="search-all" href="search.html?q=${encodeURIComponent(input.value.trim())}">Search for “${esc(input.value.trim())}” →</a>`;}input.addEventListener('input',fill);overlay.querySelector('form').addEventListener('submit',e=>{e.preventDefault();if(input.value.trim())location.href='search.html?q='+encodeURIComponent(input.value.trim());});overlay.querySelector('.site-search-close').addEventListener('click',close);overlay.addEventListener('click',e=>{if(e.target===overlay)close();});document.addEventListener('keydown',function escSearch(e){if(e.key==='Escape'){close();document.removeEventListener('keydown',escSearch);}});input.focus();}
  document.addEventListener('open-product-types',e=>{e.stopPropagation();document.body.insertAdjacentHTML('beforeend',typeManager());});
  document.addEventListener('remove-product-type',e=>{let type=e.detail;if(!confirm(`Remove product type “${type}”? Products using it will switch to another available type.`))return;productTypes=productTypes.filter(t=>t!==type);if(!productTypes.length)productTypes.push('other');let fallback=productTypes.includes('other')?'other':productTypes[0];products=products.map(p=>p.type===type?{...p,type:fallback}:p);save('sazProductTypes',productTypes);save('sazProducts',products);let select=document.querySelector('#product-form [name="type"]');if(select){let current=select.value;select.innerHTML=productTypes.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')+'<option value="__other__">Other…</option>';select.value=productTypes.includes(current)?current:'__other__';let custom=document.querySelector('#product-form [name="customType"]');if(custom&&select.value==='__other__'){custom.value=fallback;custom.style.display='block';}}document.querySelector('.type-manager-backdrop')?.remove();document.body.insertAdjacentHTML('beforeend',typeManager());});
  document.addEventListener('click',e=>{let b=e.target.closest('[data-action="gallery-image"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();galleryIndex=Number(b.dataset.index)||0;let p=product(selected),images=p.variantImages?.[chosenColor]||(p.images?.length?p.images:(p.image?[p.image]:[])),main=document.getElementById('gallery-main');if(main)main.innerHTML=artBase({...p,image:images[galleryIndex]});document.querySelectorAll('.gallery-thumb').forEach((el,i)=>el.classList.toggle('selected',i===galleryIndex));},true);
