  function applyFilters(){const grid=document.getElementById('shop-grid');if(!grid)return;let params=new URLSearchParams(location.search),department=params.get('department'),collection=params.get('collection'),sort=document.getElementById('sort')?.value||params.get('sort')||'featured',keys=[];if(department==='men'||department==='women')keys.push(department);if(sort==='newest'||sort==='sale')keys.push(sort==='newest'?'newArrivals':'sale');if(['trending','premium','casual','gifts'].includes(collection))keys.push(collection);let items=productsForPage('shopAll');for(const key of [...new Set(keys)]){let allowed=new Set(productsForPage(key).map(p=>p.id));items=items.filter(p=>allowed.has(p.id));}let cat=document.querySelector('input[name=category]:checked')?.value||'All Products',range=document.getElementById('price-range'),max=Number(range?.value??50000),sizes=[...document.querySelectorAll('.size-filter:checked')].map(x=>x.value),colors=[...document.querySelectorAll('.color-filter:checked')].map(x=>x.value),search=params.get('q')||'';if(cat!=='All Products'&&cat!=='Collections'&&cat!=='Men'&&cat!=='Women')items=items.filter(p=>p.category===cat);items=items.filter(p=>Number(p.price)<=max);if(colors.length)items=items.filter(p=>colors.includes(p.color)||(p.colors||[]).some(c=>colors.includes(c)));if(sizes.length)items=items.filter(p=>sizes.some(s=>(p.sizes||['S','M','L','XL','XXL']).includes(s)));if(search)items=items.filter(p=>`${p.name} ${p.category}`.toLowerCase().includes(search.toLowerCase()));if(sort==='low')items.sort((a,b)=>a.price-b.price);if(sort==='high')items.sort((a,b)=>b.price-a.price);if(sort==='name')items.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='newest')items.reverse();if(sort==='sale')items=items.filter(p=>Number(p.old)>Number(p.price)).sort((a,b)=>(Number(b.old)-Number(b.price))-(Number(a.old)-Number(a.price)));grid.innerHTML=items.map(card).join('');document.getElementById('result-count').textContent=`${items.length} product${items.length===1?'':'s'}`;document.getElementById('no-results').style.display=items.length?'none':'block';let label=document.getElementById('price-label');if(label)label.textContent=`৳0 – ${money(max)}`;}
  function runSearch(){let input=document.getElementById('search-input');if(!input)return;let term=input.value.toLowerCase(),items=products.filter(p=>p.name.toLowerCase().includes(term)||p.category.toLowerCase().includes(term));document.getElementById('search-grid').innerHTML=items.map(card).join('');document.getElementById('search-result-label').textContent=`${items.length} result(s) for “${input.value}”`;}
