  document.addEventListener('click',e=>{let a=e.target.closest('[data-action]');if(!a)return;e.preventDefault();let action=a.dataset.action;if(action==='menu')document.getElementById('navlinks')?.classList.toggle('open');if(action==='search'){const q=prompt('Search products');if(q!==null)location.href='search.html?q='+encodeURIComponent(q);}if(action==='add')add(a.dataset.id);if(action==='add-detail')add(a.dataset.id,quantity,chosenSize,chosenColor);if(action==='buy'){if(add(a.dataset.id,quantity,chosenSize,chosenColor))location.href='checkout.html';}if(action==='wish'){let id=a.dataset.id;wish=wish.includes(id)?wish.filter(x=>x!==id):[...wish,id];save('sazWish',wish);a.classList.toggle('active');a.textContent=wish.includes(id)?'♥':'♡';toast(wish.includes(id)?'Added to wishlist':'Removed from wishlist');}if(action==='qty-minus'){quantity=Math.max(1,quantity-1);document.getElementById('qty-val').textContent=quantity;}if(action==='qty-plus'){quantity++;document.getElementById('qty-val').textContent=quantity;}if(action==='size'){chosenSize=a.dataset.size;document.querySelectorAll('.size').forEach(x=>x.classList.toggle('selected',x===a));document.getElementById('selected-size').textContent=chosenSize;}if(action==='filters')document.getElementById('filters')?.classList.toggle('show');if(action==='clear-filter'){document.querySelectorAll('.filter-group input').forEach(x=>{if(x.type==='radio')x.checked=x.value==='All Products';else if(x.type==='checkbox')x.checked=false;});let range=document.getElementById('price-range');if(range)range.value=4000;applyFilters();}if(action==='cart-minus'||action==='cart-plus'){let x=cart.find(x=>x.id===a.dataset.id);if(x){x.qty+=action==='cart-plus'?1:-1;if(x.qty<1)cart=cart.filter(y=>y!==x);persistCart();renderCart();}}if(action==='remove'){cart=cart.filter(x=>x.id!==a.dataset.id);persistCart();renderCart();}if(action==='faq'){let item=a.closest('.faq-item');item.classList.toggle('open');a.querySelector('span').textContent=item.classList.contains('open')?'−':'＋';}if(action==='tab'){document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active',x===a));let content={description:'Made for all day, every day. Premium fabric, considered details, and a comfortable fit that moves with you.',guide:'S: chest 36–38 in · M: 38–40 in · L: 40–42 in · XL: 42–44 in · XXL: 44–46 in. For a relaxed fit, size up.',shipping:'Delivery takes 1–3 business days in Dhaka and 3–5 days elsewhere. Unused products can be returned within 7 days.'};document.getElementById('tab-content').textContent=content[a.dataset.tab];}if(action==='logout'){localStorage.removeItem('sazUser');location.reload();}if(action==='admin-logout'){localStorage.removeItem('sazAdmin');location.reload();}if(action==='admin-tab'){let view=a.dataset.view;document.querySelectorAll('.admin-nav').forEach(x=>x.classList.toggle('active',x.dataset.view===view));document.getElementById('admin-workspace').innerHTML=adminContent(view);}if(action==='account-tab'){let tab=a.dataset.tab;document.querySelectorAll('.side-nav button').forEach(x=>x.classList.toggle('active',x===a));if(tab==='Wishlist'){let el=document.getElementById('account-content');el.innerHTML=`<h1 class="page-title">Wishlist</h1><div class="grid">${products.filter(p=>wish.includes(p.id)).map(card).join('')}</div>${wish.length?'':'<p class="muted">Your wishlist is empty.</p>'}`;}if(tab==='My Orders')document.getElementById('account-content').innerHTML='<h1 class="page-title">My Orders</h1><p class="muted">Online order history is not linked to customer accounts yet. Keep your order reference and contact support for updates.</p>';if(tab==='Account Settings')document.getElementById('account-content').innerHTML=`<h1 class="page-title">Account Settings</h1><p class="muted">Signed in as ${esc(window.SAZ_API?.getUser?.()?.email||'')}</p><button class="btn secondary" data-action="logout">SIGN OUT</button>`;if(tab==='Dashboard')location.reload();}if(action==='social'){toast('Social links are coming soon');}});
