  function inventoryOptions(value){return [...new Set(String(value||'').split(',').map(x=>x.trim()).filter(Boolean))];}
  function paintStockMatrix(form, original, initial=false){
    let spot=form.querySelector('#variant-stock-editor');if(!spot)return;
    let current=new Map([...spot.querySelectorAll('[data-variant-stock]')].map(input=>[`${input.dataset.color}\u0000${input.dataset.size}`,input.value]));
    let colors=inventoryOptions(form.elements.colors.value),sizes=inventoryOptions(form.elements.sizes.value);
    if(!colors.length||!sizes.length){spot.innerHTML='<p class="muted">Enter at least one colour and one size to set stock.</p>';return;}
    let total=0;
    spot.innerHTML=`<div class="stock-matrix-head"><b>Stock by colour and size</b><small>Enter 0 for a sold-out option</small></div><div class="stock-matrix-grid">${colors.map(color=>`<div class="stock-matrix-row"><strong>${esc(color)}</strong>${sizes.map(size=>{let key=`${color}\u0000${size}`,stored=original.variants?.find(v=>v.color===color&&v.size===size),fallback=!hasVariants(original)&&color===colors[0]&&size===sizes[0]?cleanStock(original.stock):0,value=current.has(key)?current.get(key):initial?(stored?cleanStock(stored.stock):fallback):stored?cleanStock(stored.stock):0;total+=Number(value)||0;return `<label>${esc(size)}<input type="number" min="0" max="999999" step="1" required data-variant-stock data-color="${esc(color)}" data-size="${esc(size)}" value="${esc(value)}" aria-label="${esc(color)} ${esc(size)} stock"></label>`}).join('')}</div>`).join('')}</div><p class="stock-matrix-total">Total: <strong>${total}</strong> in stock</p>${!hasVariants(original)&&cleanStock(original.stock)>0?'<small class="muted">Existing stock was placed in the first colour and size. Distribute it across the grid before saving.</small>':''}`;
  }
